import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        String s = "test";
        assertTrue("Should return true for the same instance", StringUtils.equals(s, s));
        assertTrue("Should return true for null same instance", StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_SecondIsNull() {
        String s = "test";
        assertFalse("Should return false when cs2 is null and cs1 is not", StringUtils.equals(s, null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        String s1 = "abc";
        String s2 = "abc";
        assertTrue("Should return true for equal strings", StringUtils.equals(s1, s2));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        String s1 = "abc";
        String s2 = "def";
        assertFalse("Should return false for unequal strings", StringUtils.equals(s1, s2));
    }

    @Test
    public void testEquals_BothStrings_DifferentLength() {
        String s1 = "abc";
        String s2 = "abcd";
        assertFalse("Should return false for strings of different length", StringUtils.equals(s1, s2));
    }

    @Test
    public void testEquals_MixedTypes_Equal() {
        // Using StringBuilder to test the CharSequence branch (not both Strings)
        CharSequence cs1 = new StringBuilder("abc");
        CharSequence cs2 = "abc";
        // Note: The logic uses regionMatches with Math.max length. 
        // If cs1 is StringBuilder and cs2 is String, it falls to regionMatches.
        assertTrue("Should return true for matching CharSequences of different implementation", 
                   StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_NotEqual() {
        CharSequence cs1 = new StringBuilder("abc");
        CharSequence cs2 = "abd";
        assertFalse("Should return false for non-matching CharSequences", StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_DifferentLength() {
        CharSequence cs1 = new StringBuilder("abc");
        CharSequence cs2 = "abcd";
        assertFalse("Should return false when lengths differ in non-string branch", 
                    StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_FirstIsNull() {
        // cs1 is null, cs2 is not null. 
        // cs1 == cs2 is false. cs2 == null is false.
        // cs1 instanceof String is false.
        // Falls to regionMatches. Since cs1 is null, regionMatches behavior depends on implementation,
        // but in StringUtils logic, it will likely throw or return false.
        // According to the provided code, if cs1 is null, it skips the String check and calls regionMatches.
        // Most implementations of regionMatches will handle null cs1 by returning false or throwing.
        // However, based on the logic:
        assertFalse("Should return false when cs1 is null and cs2 is not", StringUtils.equals(null, "abc"));
    }

    @Test
    public void testEquals_EmptyStrings() {
        assertTrue(StringUtils.equals("", ""));
        assertFalse(StringUtils.equals("", " "));
    }
}
